//! Settings of the API, read from the environment (see .env.example).

/// Settings of the API. The tests build their own.
#[derive(Clone, Debug, Default)]
pub struct Settings {
    /// Connection URL of the database (DATABASE_URL)
    pub database_url: String,
}

impl Settings {
    pub fn from_env() -> Self {
        let read = |name: &str| std::env::var(name).ok().filter(|value| !value.is_empty());
        Self {
            database_url: read("DATABASE_URL").unwrap_or_else(|| "mysql://api:change-me@localhost:3306/api".to_string()),
        }
    }
}

