//! Where customers are kept.

use async_trait::async_trait;
use sea_orm::ColumnTrait;
use sea_orm::NotSet;
use sea_orm::Order;
use sea_orm::QueryFilter;
use sea_orm::{ActiveModelTrait, DatabaseConnection, EntityTrait, PaginatorTrait, QueryOrder, QuerySelect, Set};

use crate::common::error::ApiError;
use crate::common::list::{ListQuery, ListResult};
use crate::customer::entity as entity;
use crate::customer::model::Customer;

/// What a list of customers can filter by: a field that has a value must be equal to it.
#[derive(Clone, Debug, Default)]
pub struct CustomerFilters {
    pub name: Option<String>,
    pub email: Option<String>,
}

/// Where customers are kept. The service depends only on this trait.
#[async_trait]
pub trait CustomerRepository: Send + Sync {
    /// Items equal to every filter, in order, within the window; and how many match.
    async fn list(&self, query: &ListQuery<CustomerFilters>) -> Result<ListResult<Customer>, ApiError>;

    /// The item with this key, or None when there is none.
    async fn get(&self, key: i64) -> Result<Option<Customer>, ApiError>;

    /// Stores a new item and assigns its key; returns it as stored.
    async fn add(&self, item: Customer) -> Result<Customer, ApiError>;

    /// Stores the new state of an existing item and returns it.
    async fn update(&self, item: Customer) -> Result<Customer, ApiError>;

    /// Removes an existing item.
    async fn delete(&self, key: i64) -> Result<(), ApiError>;
}

/// Keeps customers in the database with SeaORM.
pub struct SeaOrmCustomerRepository {
    database: DatabaseConnection,
}

impl SeaOrmCustomerRepository {
    pub fn new(database: DatabaseConnection) -> Self {
        Self { database }
    }
}

/// The row of an item: every field in its column.
fn to_row(item: &Customer) -> entity::ActiveModel {
    entity::ActiveModel {
        id: Set(item.id.clone()),
        name: Set(item.name.clone()),
        email: Set(item.email.clone()),
        password: Set(item.password.clone()),
        phone: Set(item.phone.clone()),
        address: Set(item.address.as_ref().map(|value| serde_json::to_string(value).unwrap_or_default())),
        created_at: Set(item.created_at.map(|value| value.naive_utc())),
    }
}

fn to_item(row: entity::Model) -> Customer {
    Customer {
        id: row.id,
        name: row.name,
        email: row.email,
        password: row.password,
        phone: row.phone,
        address: row.address.and_then(|text| serde_json::from_str(&text).ok()),
        created_at: row.created_at.map(|value| value.and_utc()),
    }
}

#[async_trait]
impl CustomerRepository for SeaOrmCustomerRepository {
    async fn list(&self, query: &ListQuery<CustomerFilters>) -> Result<ListResult<Customer>, ApiError> {
        let mut select = entity::Entity::find();
        if let Some(value) = &query.filters.name {
            select = select.filter(entity::Column::Name.eq(value.clone()));
        }
        if let Some(value) = &query.filters.email {
            select = select.filter(entity::Column::Email.eq(value.clone()));
        }
        let total = select.clone().count(&self.database).await?;
        let order = if query.descending { Order::Desc } else { Order::Asc };
        // Items without a value go last, whatever the order; the key breaks ties
        select = match query.sort_field.as_deref() {
            Some("name") => select.order_by(entity::Column::Name.is_null(), Order::Asc).order_by(entity::Column::Name, order),
            Some("email") => select.order_by(entity::Column::Email.is_null(), Order::Asc).order_by(entity::Column::Email, order),
            _ => select,
        };
        select = select.order_by_asc(entity::Column::Id).offset(query.offset);
        if let Some(limit) = query.limit {
            select = select.limit(limit);
        }
        let items = select.all(&self.database).await?.into_iter().map(to_item).collect();
        Ok(ListResult { items, total })
    }

    async fn get(&self, key: i64) -> Result<Option<Customer>, ApiError> {
        Ok(entity::Entity::find_by_id(key).one(&self.database).await?.map(to_item))
    }

    async fn add(&self, item: Customer) -> Result<Customer, ApiError> {
        let mut row = to_row(&item);
        row.id = NotSet;
        Ok(to_item(row.insert(&self.database).await?))
    }

    async fn update(&self, item: Customer) -> Result<Customer, ApiError> {
        Ok(to_item(to_row(&item).update(&self.database).await?))
    }

    async fn delete(&self, key: i64) -> Result<(), ApiError> {
        entity::Entity::delete_by_id(key).exec(&self.database).await?;
        Ok(())
    }
}

