//! The API: the state every handler shares, and the router with every route.

pub mod common;
pub mod customer;
pub mod database;
pub mod order;
pub mod product;
pub mod shared;

use std::sync::Arc;

use axum::Router;
use tower_http::catch_panic::CatchPanicLayer;

use crate::common::error::{no_route, panic_response, wrong_method};
use crate::common::settings::Settings;
use crate::customer::repository::{SeaOrmCustomerRepository, CustomerRepository};
use crate::customer::service::CustomerService;
use crate::order::repository::{SeaOrmOrderRepository, OrderRepository};
use crate::order::service::OrderService;
use crate::product::repository::{SeaOrmProductRepository, ProductRepository};
use crate::product::service::ProductService;

/// What every handler shares: the settings and the service of each resource.
#[derive(Clone)]
pub struct AppState {
    pub settings: Arc<Settings>,
    pub customers: Arc<CustomerService>,
    pub products: Arc<ProductService>,
    pub orders: Arc<OrderService>,
}

/// Builds the API with its storage: the router that main serves and the tests call.
pub async fn build(settings: Settings) -> Result<Router, Box<dyn std::error::Error>> {
    let database = database::connect(&settings).await?;
    let customer_repository: Arc<dyn CustomerRepository> = Arc::new(SeaOrmCustomerRepository::new(database.clone()));
    let product_repository: Arc<dyn ProductRepository> = Arc::new(SeaOrmProductRepository::new(database.clone()));
    let order_repository: Arc<dyn OrderRepository> = Arc::new(SeaOrmOrderRepository::new(database.clone()));
    let state = AppState {
        settings: Arc::new(settings),
        customers: Arc::new(CustomerService::new(customer_repository.clone())),
        products: Arc::new(ProductService::new(product_repository.clone())),
        orders: Arc::new(OrderService::new(order_repository.clone(), customer_repository.clone(), product_repository.clone())),
    };
    Ok(Router::new()
        .merge(crate::customer::routes::router())
        .merge(crate::product::routes::router())
        .merge(crate::order::routes::router())
        .fallback(no_route)
        .method_not_allowed_fallback(wrong_method)
        .layer(CatchPanicLayer::custom(panic_response))
        .with_state(state))
}

