//! Where orders are kept.

use async_trait::async_trait;
use sea_orm::NotSet;
use sea_orm::{ActiveModelTrait, DatabaseConnection, EntityTrait, PaginatorTrait, QueryOrder, QuerySelect, Set};

use crate::common::error::ApiError;
use crate::common::list::{ListQuery, ListResult};
use crate::order::entity as entity;
use crate::order::model::Order;
use crate::shared::order_status::OrderStatus;

/// What a list of orders can filter by: a field that has a value must be equal to it.
#[derive(Clone, Debug, Default)]
pub struct OrderFilters {}

/// Where orders are kept. The service depends only on this trait.
#[async_trait]
pub trait OrderRepository: Send + Sync {
    /// Items equal to every filter, in order, within the window; and how many match.
    async fn list(&self, query: &ListQuery<OrderFilters>) -> Result<ListResult<Order>, ApiError>;

    /// The item with this key, or None when there is none.
    async fn get(&self, key: i64) -> Result<Option<Order>, ApiError>;

    /// Stores a new item and assigns its key; returns it as stored.
    async fn add(&self, item: Order) -> Result<Order, ApiError>;

    /// Stores the new state of an existing item and returns it.
    async fn update(&self, item: Order) -> Result<Order, ApiError>;

    /// Removes an existing item.
    async fn delete(&self, key: i64) -> Result<(), ApiError>;
}

/// Keeps orders in the database with SeaORM.
pub struct SeaOrmOrderRepository {
    database: DatabaseConnection,
}

impl SeaOrmOrderRepository {
    pub fn new(database: DatabaseConnection) -> Self {
        Self { database }
    }
}

/// The row of an item: every field in its column.
fn to_row(item: &Order) -> entity::ActiveModel {
    entity::ActiveModel {
        id: Set(item.id.clone()),
        customer_id: Set(item.customer_id.clone()),
        lines: Set(item.lines.as_ref().map(|value| serde_json::to_string(value).unwrap_or_default())),
        status: Set(item.status.map(|value| value.value().to_string())),
        total: Set(item.total.clone()),
        notes: Set(item.notes.clone()),
        created_at: Set(item.created_at.map(|value| value.naive_utc())),
        updated_at: Set(item.updated_at.map(|value| value.naive_utc())),
    }
}

fn to_item(row: entity::Model) -> Order {
    Order {
        id: row.id,
        customer_id: row.customer_id,
        lines: row.lines.and_then(|text| serde_json::from_str(&text).ok()),
        status: row.status.as_deref().and_then(OrderStatus::from_value),
        total: row.total,
        notes: row.notes,
        created_at: row.created_at.map(|value| value.and_utc()),
        updated_at: row.updated_at.map(|value| value.and_utc()),
    }
}

#[async_trait]
impl OrderRepository for SeaOrmOrderRepository {
    async fn list(&self, query: &ListQuery<OrderFilters>) -> Result<ListResult<Order>, ApiError> {
        let mut select = entity::Entity::find();
        let total = select.clone().count(&self.database).await?;
        select = select.order_by_asc(entity::Column::Id).offset(query.offset);
        if let Some(limit) = query.limit {
            select = select.limit(limit);
        }
        let items = select.all(&self.database).await?.into_iter().map(to_item).collect();
        Ok(ListResult { items, total })
    }

    async fn get(&self, key: i64) -> Result<Option<Order>, ApiError> {
        Ok(entity::Entity::find_by_id(key).one(&self.database).await?.map(to_item))
    }

    async fn add(&self, item: Order) -> Result<Order, ApiError> {
        let mut row = to_row(&item);
        row.id = NotSet;
        Ok(to_item(row.insert(&self.database).await?))
    }

    async fn update(&self, item: Order) -> Result<Order, ApiError> {
        Ok(to_item(to_row(&item).update(&self.database).await?))
    }

    async fn delete(&self, key: i64) -> Result<(), ApiError> {
        entity::Entity::delete_by_id(key).exec(&self.database).await?;
        Ok(())
    }
}

