}

impl From<Product> for ProductResponse {
    fn from(item: Product) -> Self {
        Self {
            id: item.id,
            sku: item.sku,
            name: item.name,
            description: item.description,
            price: item.price,
            stock: item.stock,
            active: item.active,
        }
    }
}

