//! Where products are kept.

use async_trait::async_trait;
use sea_orm::NotSet;
use sea_orm::{ActiveModelTrait, DatabaseConnection, EntityTrait, PaginatorTrait, QueryOrder, QuerySelect, Set};

use crate::common::error::ApiError;
use crate::common::list::{ListQuery, ListResult};
use crate::product::entity as entity;
use crate::product::model::Product;

/// What a list of products can filter by: a field that has a value must be equal to it.
#[derive(Clone, Debug, Default)]
pub struct ProductFilters {}

/// Where products are kept. The service depends only on this trait.
#[async_trait]
pub trait ProductRepository: Send + Sync {
    /// Items equal to every filter, in order, within the window; and how many match.
    async fn list(&self, query: &ListQuery<ProductFilters>) -> Result<ListResult<Product>, ApiError>;

    /// The item with this key, or None when there is none.
    async fn get(&self, key: i64) -> Result<Option<Product>, ApiError>;

    /// Stores a new item and assigns its key; returns it as stored.
    async fn add(&self, item: Product) -> Result<Product, ApiError>;

    /// Stores the new state of an existing item and returns it.
    async fn update(&self, item: Product) -> Result<Product, ApiError>;

    /// Removes an existing item.
    async fn delete(&self, key: i64) -> Result<(), ApiError>;
}

/// Keeps products in the database with SeaORM.
pub struct SeaOrmProductRepository {
    database: DatabaseConnection,
}

impl SeaOrmProductRepository {
    pub fn new(database: DatabaseConnection) -> Self {
        Self { database }
    }
}

/// The row of an item: every field in its column.
fn to_row(item: &Product) -> entity::ActiveModel {
    entity::ActiveModel {
        id: Set(item.id.clone()),
        sku: Set(item.sku.clone()),
        name: Set(item.name.clone()),
        description: Set(item.description.clone()),
        price: Set(item.price.clone()),
        stock: Set(item.stock.clone()),
        active: Set(item.active.clone()),
    }
}

fn to_item(row: entity::Model) -> Product {
    Product {
        id: row.id,
        sku: row.sku,
        name: row.name,
        description: row.description,
        price: row.price,
        stock: row.stock,
        active: row.active,
    }
}

#[async_trait]
impl ProductRepository for SeaOrmProductRepository {
    async fn list(&self, query: &ListQuery<ProductFilters>) -> Result<ListResult<Product>, ApiError> {
        let mut select = entity::Entity::find();
        let total = select.clone().count(&self.database).await?;
        select = select.order_by_asc(entity::Column::Id).offset(query.offset);
        if let Some(limit) = query.limit {
            select = select.limit(limit);
        }
        let items = select.all(&self.database).await?.into_iter().map(to_item).collect();
        Ok(ListResult { items, total })
    }

    async fn get(&self, key: i64) -> Result<Option<Product>, ApiError> {
        Ok(entity::Entity::find_by_id(key).one(&self.database).await?.map(to_item))
    }

    async fn add(&self, item: Product) -> Result<Product, ApiError> {
        let mut row = to_row(&item);
        row.id = NotSet;
        Ok(to_item(row.insert(&self.database).await?))
    }

    async fn update(&self, item: Product) -> Result<Product, ApiError> {
        Ok(to_item(to_row(&item).update(&self.database).await?))
    }

    async fn delete(&self, key: i64) -> Result<(), ApiError> {
        entity::Entity::delete_by_id(key).exec(&self.database).await?;
        Ok(())
    }
}

