//! Tests of the customers endpoints.

use crate::support::{Api, headers, parse, text, without};

#[tokio::test]
async fn creates_a_customer() {
    let api = Api::new().await;
    let payload = api.customer_payload(0).await;

    let response = api.post("/customers", &payload, &headers()).await;

    response.assert_status(201);
    assert!(response.json.get("id").is_some());
    assert_eq!(payload["name"], response.json["name"]);
    assert_eq!(payload["email"], response.json["email"]);
    assert_eq!(payload["phone"], response.json["phone"]);
}

#[tokio::test]
async fn rejects_a_customer_without_name() {
    let api = Api::new().await;
    let payload = without(api.customer_payload(0).await, "name");

    let response = api.post("/customers", &payload, &headers()).await;

    response.assert_status(400);
    assert_eq!(response.json["error"]["code"], "validation_error");
    let details = response.json["error"]["details"].as_array().cloned().unwrap_or_default();
    assert!(details.iter().any(|detail| detail["field"] == "name"));
}

#[tokio::test]
async fn gets_a_customer() {
    let api = Api::new().await;
    let created = api.create_customer(0).await;
    let key = text(&created["id"]);

    let response = api.get(&format!("/customers/{key}"), &headers()).await;

    response.assert_status(200);
    assert_eq!(created, response.json);
