//! Base of the tests: a new application for each test, so each one starts with empty storage.

// Each test module uses only some of these helpers
#![allow(dead_code)]

use axum::Router;
use axum::body::Body;
use axum::http::Request;
use serde_json::Value;
use shop_api::build;
use shop_api::common::settings::Settings;
use shop_api::database::drop_tables;
use tokio::sync::{Mutex, MutexGuard};
use tower::ServiceExt;
use uuid::Uuid;

/// Turns on a shared database: one test at a time, each with the tables dropped first.
static TURN: Mutex<()> = Mutex::const_new(());

/// Settings of the application under test. TEST_DATABASE_URL runs the tests on that database, emptied first;
/// without it, each test has its own SQLite file.
async fn settings() -> (Settings, Option<MutexGuard<'static, ()>>) {
    let shared = std::env::var("TEST_DATABASE_URL").unwrap_or_default();
    let (database_url, turn) = if shared.is_empty() {
        let file = std::env::temp_dir().join(format!("api-test-{}.db", Uuid::new_v4()));
        (format!("sqlite://{}?mode=rwc", file.display()), None)
    } else {
        let turn = TURN.lock().await;
        let database = sea_orm::Database::connect(&shared).await.expect("the test database answers");
        drop_tables(&database).await.expect("the tables can be dropped");
        database.close().await.ok();
        (shared, Some(turn))
    };
    let settings = Settings {
        database_url,
        ..Default::default()
    };
    (settings, turn)
}

/// Headers of a client allowed to call every endpoint.
pub fn headers() -> Vec<(&'static str, String)> {
    Vec::new()
}

/// The application under test, called through its router.
pub struct Api {
    router: Router,
    _turn: Option<MutexGuard<'static, ()>>,
}

/// The answer of a request in a test: its status and its JSON body (null when it has none).
pub struct TestResponse {
    pub status: u16,
    pub text: String,
    pub json: Value,
}

impl TestResponse {
    pub fn assert_status(&self, expected: u16) {
        assert_eq!(expected, self.status, "{}", self.text);
    }
}

impl Api {
    pub async fn new() -> Self {
        let (settings, turn) = settings().await;
        let router = build(settings).await.expect("the API starts");
        Self { router, _turn: turn }
    }

    pub async fn get(&self, path: &str, headers: &[(&'static str, String)]) -> TestResponse {
        self.send("GET", path, None, headers).await
    }

    pub async fn post(&self, path: &str, body: &Value, headers: &[(&'static str, String)]) -> TestResponse {
        self.send("POST", path, Some(body), headers).await
    }

    pub async fn put(&self, path: &str, body: &Value, headers: &[(&'static str, String)]) -> TestResponse {
        self.send("PUT", path, Some(body), headers).await
    }

    pub async fn patch(&self, path: &str, body: &Value, headers: &[(&'static str, String)]) -> TestResponse {
        self.send("PATCH", path, Some(body), headers).await
    }

    pub async fn delete(&self, path: &str, headers: &[(&'static str, String)]) -> TestResponse {
        self.send("DELETE", path, None, headers).await
    }

    /// Sends a request, with a JSON body when there is one.
    pub async fn send(&self, method: &str, path: &str, body: Option<&Value>, headers: &[(&'static str, String)]) -> TestResponse {
        let mut request = Request::builder().method(method).uri(path);
        for (name, value) in headers {
            request = request.header(*name, value);
        }
        let request = match body {
            Some(body) => request.header("content-type", "application/json").body(Body::from(body.to_string())),
            None => request.body(Body::empty()),
        }
        .expect("the request is valid");
        let response = self.router.clone().oneshot(request).await.expect("the router answers");
        let status = response.status().as_u16();
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX).await.expect("the body can be read");
        let text = String::from_utf8_lossy(&bytes).into_owned();
        let json = serde_json::from_str(&text).unwrap_or(Value::Null);
        TestResponse { status, text, json }
    }

    /// A valid body to create a customer, with the items it refers to created first.
    pub async fn customer_payload(&self, variant: usize) -> Value {
        let body = if variant == 0 { parse("{\"name\":\"name 1\",\"email\":\"email 1\",\"password\":\"password 1\",\"phone\":\"phone 1\",\"address\":{\"street\":\"street 1\",\"city\":\"city 1\",\"postalCode\":\"postalCode 1\",\"country\":\"country 1\"}}") } else { parse("{\"name\":\"name 2\",\"email\":\"email 2\",\"password\":\"password 2\",\"phone\":\"phone 2\",\"address\":{\"street\":\"street 2\",\"city\":\"city 2\",\"postalCode\":\"postalCode 2\",\"country\":\"country 2\"}}") };
        body
    }

    /// Creates a customer and returns it as the API answers.
    pub async fn create_customer(&self, variant: usize) -> Value {
        let payload = self.customer_payload(variant).await;
        let response = self.post("/customers", &payload, &headers()).await;
        response.assert_status(201);
        response.json
    }

    /// A valid body to create a product, with the items it refers to created first.
    pub async fn product_payload(&self, variant: usize) -> Value {
        let body = if variant == 0 { parse("{\"sku\":\"sku 1\",\"name\":\"name 1\",\"description\":\"description 1\",\"price\":1.5,\"stock\":1.5,\"active\":true}") } else { parse("{\"sku\":\"sku 2\",\"name\":\"name 2\",\"description\":\"description 2\",\"price\":2,\"stock\":2,\"active\":false}") };
        body
    }

    /// Creates a product and returns it as the API answers.
    pub async fn create_product(&self, variant: usize) -> Value {
        let payload = self.product_payload(variant).await;
        let response = self.post("/products", &payload, &headers()).await;
        response.assert_status(201);
        response.json
    }

    /// A valid body to create an order, with the items it refers to created first.
    pub async fn order_payload(&self, variant: usize) -> Value {
        let mut body = if variant == 0 { parse("{\"customerId\":null,\"lines\":[{\"productId\":null,\"quantity\":1.5,\"unitPrice\":1.5}],\"status\":\"pending\",\"total\":1.5,\"notes\":\"notes 1\"}") } else { parse("{\"customerId\":null,\"lines\":[{\"productId\":null,\"quantity\":2,\"unitPrice\":2}],\"status\":\"paid\",\"total\":2,\"notes\":\"notes 2\"}") };
        body = with(body, "/customerId", self.create_customer(0).await["id"].clone());
        body = with(body, "/lines/0/productId", self.create_product(0).await["id"].clone());
        body
    }

    /// Creates an order and returns it as the API answers.
    pub async fn create_order(&self, variant: usize) -> Value {
        let payload = self.order_payload(variant).await;
        let response = self.post("/orders", &payload, &headers()).await;
        response.assert_status(201);
        response.json
    }
}

/// A JSON value from its text.
pub fn parse(text: &str) -> Value {
    serde_json::from_str(text).expect("the JSON of the test is valid")
}

/// The text of a key in a JSON answer, for a path.
pub fn text(value: &Value) -> String {
    value.as_str().map(String::from).unwrap_or_else(|| value.to_string())
}

/// A copy of a JSON value with another value at a JSON pointer: "/lines/0/productId".
pub fn with(mut value: Value, pointer: &str, new: Value) -> Value {
    let (parent, last) = pointer.rsplit_once('/').expect("the pointer starts with /");
    let last = last.replace("~1", "/").replace("~0", "~");
    match value.pointer_mut(parent) {
        Some(Value::Object(map)) => {
            map.insert(last, new);
        }
        Some(Value::Array(items)) => {
            if let Some(item) = last.parse::<usize>().ok().and_then(|index| items.get_mut(index)) {
                *item = new;
            }
        }
        _ => {}
    }
    value
}

/// A copy of a JSON object without a field.
pub fn without(mut value: Value, field: &str) -> Value {
    if let Some(map) = value.as_object_mut() {
        map.remove(field);
    }
    value
}
